SELECT "agencyid", "sk_recorddateid", "sk_updatedateid", "batchid", "iscustomer", "lastname", "firstname", "middleinitial", "gender", "addressline1", "addressline2", "postalcode", "city", "state", "country", "phone", "income", "numbercars", "numberchildren", "maritalstatus", "age", "creditrating", "ownorrentflag", "employer", "numbercreditcards", "networth", "marketingnameplate" FROM (SELECT TRY_CAST((CAST(p.AgencyID AS TEXT)) AS TEXT) AS "agencyid", TRY_CAST((CAST(20170707 AS INT)) AS INT) AS "sk_recorddateid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_updatedateid", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS DECIMAL(5)) AS "batchid", TRY_CAST((FALSE) AS BOOLEAN) AS "iscustomer", TRY_CAST((CAST(p.LastName AS TEXT)) AS TEXT) AS "lastname", TRY_CAST((CAST(p.FirstName AS TEXT)) AS TEXT) AS "firstname", TRY_CAST((CAST(p.MiddleInitial AS TEXT)) AS TEXT) AS "middleinitial", TRY_CAST((CASE WHEN p.Gender IS NULL THEN NULL WHEN UPPER(p.Gender) = 'M' THEN 'M' WHEN UPPER(p.Gender) = 'F' THEN 'F' ELSE 'U' END) AS TEXT) AS "gender", TRY_CAST((CAST(p.AddressLine1 AS TEXT)) AS TEXT) AS "addressline1", TRY_CAST((p.AddressLine2) AS TEXT) AS "addressline2", TRY_CAST((CAST(p.PostalCode AS TEXT)) AS TEXT) AS "postalcode", TRY_CAST((CAST(p.City AS TEXT)) AS TEXT) AS "city", TRY_CAST((CAST(p.State AS TEXT)) AS TEXT) AS "state", TRY_CAST((CAST(p.Country AS TEXT)) AS TEXT) AS "country", TRY_CAST((CAST(p.Phone AS TEXT)) AS TEXT) AS "phone", TRY_CAST((p.Income) AS DECIMAL(9)) AS "income", TRY_CAST((p.NumberCars) AS DECIMAL(2)) AS "numbercars", TRY_CAST((p.NumberChildren) AS DECIMAL(2)) AS "numberchildren", TRY_CAST((p.MaritalStatus) AS TEXT) AS "maritalstatus", TRY_CAST((p.Age) AS DECIMAL(3)) AS "age", TRY_CAST((p.CreditRating) AS DECIMAL(4)) AS "creditrating", TRY_CAST((p."OwnOrRentFlag") AS TEXT) AS "ownorrentflag", TRY_CAST((CAST(p.Employer AS TEXT)) AS TEXT) AS "employer", TRY_CAST((p.NumberCreditCards) AS DECIMAL(2)) AS "numbercreditcards", TRY_CAST((p.NetWorth) AS DECIMAL(12)) AS "networth", TRY_CAST((CAST(NULL AS TEXT)) AS TEXT) AS "marketingnameplate" FROM "Source"."Prospect" AS p);
